from itertools import permutations

langs = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "Germany": {"Korean", "French", "English", "German"},
}

def comm(a, b):
    return len(langs[a] & langs[b]) > 0

def ok(order):
    pos = {n: i for i, n in enumerate(order)}
    def nbrs(n):
        i = pos[n]
        return [order[j] for j in (i - 1, i + 1) if 0 <= j < 4]
    if not pos["South Korea"] > pos["Germany"]:
        return False
    if any(comm("South Korea", x) for x in nbrs("South Korea")):
        return False
    if any(comm("France", x) for x in nbrs("France")):
        return False
    if sum(comm("Britain", x) for x in nbrs("Britain")) != 1:
        return False
    return True

solutions = [p for p in permutations(langs) if ok(p)]
print("All valid arrangements (room 1..4):", solutions)

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}
for k, v in options.items():
    print(k, v, "valid" if ok(v) else "invalid")

claimed = "D"
print("Claimed option", claimed, "valid:", ok(options[claimed]))
print("CHECK PASS" if ok(options[claimed]) and len(solutions) == 1 else "CHECK FAIL")
